import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String input = br.readLine().trim();

        boolean[][] seen = new boolean[4][14];
        int[] count = new int[4];
        boolean[] duplicate = new boolean[4];

        for (int i = 0; i < input.length(); i += 3) {
            int value = Integer.parseInt(input.substring(i, i + 2));
            char suitChar = input.charAt(i + 2);

            int suit;
            switch (suitChar) {
                case 'C': suit = 0; break;
                case 'E': suit = 1; break;
                case 'U': suit = 2; break;
                default: suit = 3;
            }

            if (seen[suit][value]) {
                duplicate[suit] = true;
            } else {
                seen[suit][value] = true;
                count[suit]++;
            }
        }

        StringBuilder output = new StringBuilder();
        for (int suit = 0; suit < 4; suit++) {
            if (duplicate[suit]) {
                output.append("erro");
            } else {
                output.append(13 - count[suit]);
            }
            output.append('\n');
        }

        System.out.print(output);
    }
}
